import math

n = int(input())
for i in range(n):
    kind = input()
    known = input()
    length = float(input())
    if kind == "45-45-90":
        if known == "leg":
            unit = length
        else:
            unit = length / math.sqrt(2)
        print(f"legs {unit:.4f}, {unit:.4f}, hyp {unit * math.sqrt(2):.4f}")
    else:
        if known == "short":
            unit = length
        elif known == "long":
            unit = length / math.sqrt(3)
        else:
            unit = length / 2
        print(f"short {unit:.4f}, long {unit * math.sqrt(3):.4f}, hyp {2 * unit:.4f}")

import math

def tan_deg(d):
    return math.tan(math.radians(d))

n = int(input())
for i in range(n):
    kind = input()
    if kind == "two":
        far = float(input())
        near = float(input())
        gap = float(input())
        x = gap * tan_deg(far) / (tan_deg(near) - tan_deg(far))
        h = x * tan_deg(near)
        print(f"two: height {h:.2f}")
    else:
        p = float(input())
        q = float(input())
        if kind == "height":
            answer = p * tan_deg(q)
        elif kind == "distance":
            answer = p / tan_deg(q)
        else:
            answer = math.degrees(math.atan(p / q))
        print(f"{kind}: {answer:.2f}")
